expressionInfo.expression:
var C = {'A':'#2ecc71','B':'#a8d92e','C':'#f1c40f','D':'#e67e22','Ev':'#e74c3c','E':'#8e2424'};
function col(p) { if (IsEmpty(p) || !HasKey(C, p)) { return '#bbbbbb'; } return C[p]; }
var p = $feature.pal;
var h = '<div style="display:flex;align-items:center;gap:10px;margin-bottom:6px">' +
  '<span style="min-width:48px;text-align:center;padding:4px 10px;border-radius:5px;background:' + col(p) +
  ';color:#fff;font-weight:bold;font-size:22px">' + DefaultValue(p, '–') + '</span>' +
  '<div><b>PAL at the 1400 obs</b><br><span style="font-size:12px">ERC ' + DefaultValue($feature.erc, '–') +
  ' · IC ' + DefaultValue($feature.ic, '–') + '</span></div></div>';
var ov = $feature.pal_override;
if (!IsEmpty(ov)) {
  var oc = $feature.override_comment; var ob = $feature.override_by;
  var note = '★ Adjusted PAL ' + ov + ' (calculated ' + DefaultValue($feature.pal_raw, '–') + ') until ' + $feature.override_until;
  if (!IsEmpty(oc)) { note += ' — ' + oc; }
  if (!IsEmpty(ob)) { note += ' (' + ob + ')'; }
  h += '<div style="font-size:12px;background:#fff4d6;padding:4px 6px;border-radius:4px;margin-bottom:6px">' + note + '</div>';
}
if (!IsEmpty($feature.fc_dates)) {
  var d = Split($feature.fc_dates, ','); var pp = Split($feature.fc_pal, ','); var tt = Split($feature.fc_type, ',');
  var today = Text(ChangeTimeZone(Now(), 'America/Los_Angeles'), 'YYYY-MM-DD');
  var tbl = ''; var r1 = ''; var r2 = ''; var n = 0; var todayPal = '';
  for (var i in d) {
    var dt = Date(Number(Left(d[i], 4)), Number(Mid(d[i], 5, 2)) - 1, Number(Right(d[i], 2)));
    var isToday = d[i] == today;
    if (isToday) { todayPal = pp[i] + ' (' + tt[i] + ')'; }
    var bd = IIf(isToday, 'border:2px solid #000;', 'border:1px solid #fff;');
    r1 += '<td style="text-align:center;font-size:10px;padding:1px;width:14%">' + Text(dt, 'ddd') + ' ' + Text(dt, 'M/D') + '</td>';
    r2 += '<td style="text-align:center;padding:2px 1px;' + bd + 'background:' + col(pp[i]) + ';color:#fff;font-weight:bold;font-size:13px">' +
          pp[i] + ' <span style="font-size:9px;font-weight:normal">' + IIf(tt[i] == '-', '', tt[i]) + '</span></td>';
    n += 1;
    if (n % 7 == 0) { tbl += '<tr>' + r1 + '</tr><tr>' + r2 + '</tr>'; r1 = ''; r2 = ''; }
  }
  if (r1 != '') { tbl += '<tr>' + r1 + '</tr><tr>' + r2 + '</tr>'; }
  if (todayPal != '') {
    h += '<div style="font-size:12px;margin-bottom:4px">Today (daily peak): <b>' + todayPal + '</b></div>';
  }
  h += '<div style="font-size:12px;font-weight:bold;margin:4px 0 2px">13-day PAL — daily peak ERC/IC (O = observed, F = forecast)</div>' +
       '<table style="border-collapse:collapse;width:100%;table-layout:fixed">' + tbl + '</table>';
}
h += '<div style="font-size:11px;color:#666;margin-top:6px">' + DefaultValue($feature.forest, 'Not a forest PAL station') +
     ' · ' + DefaultValue($feature.classification, '') + ' · ' + Round(DefaultValue($feature.elevation_ft, 0), 0) + ' ft<br>' +
     'Source: <a href="https://gacc.nifc.gov/oscc/predictive/weather/pal_combined_report.html" target="_blank">CA PAL Combined Report</a>, generated ' +
     DefaultValue($feature.report_time, '') + '</div>';
return { type: 'text', text: h };
